    @EventHandler
    public void handle( CreateCase_Event event) {
        entityManager.persist(new Case_(event.getCase_Id(), event.getCaseNumber(), event.getSubject(), event.getDescription(), event.getSlaDue(), event.getOrganization(), event.getAccount(), event.getContact(), event.getOwner(), event.getTeam(), event.getActivities(), event.getCaseComments(), event.getEmails(), event.getRelatedOpportunities(), event.getStatus(), event.getPriority(), event.getOrigin(), event.getSeverity()));
    }

